final_sql:
WITH v_Examination AS (SELECT Examination.ID AS ID, Examination.`Examination Date` AS `Examination Date`, Examination.`aCL IgG` AS `aCL IgG`, Examination.`aCL IgM` AS `aCL IgM`, Examination.ANA AS ANA, Examination.`ANA Pattern` AS `ANA Pattern`, Examination.`aCL IgA` AS `aCL IgA`, Examination.Diagnosis AS Diagnosis, Examination.KCT AS KCT, Examination.RVVT AS RVVT, Examination.LAC AS LAC, Examination.Symptoms AS Symptoms, Examination.Thrombosis AS Thrombosis, Patient.SEX AS SEX, Patient.Birthday AS Birthday FROM Examination LEFT JOIN Patient AS Patient ON Examination.ID = Patient.ID), v_Laboratory AS (SELECT Laboratory.ID AS ID, Laboratory.Date AS Date, Laboratory.GOT AS GOT, Laboratory.GPT AS GPT, Laboratory.LDH AS LDH, Laboratory.ALP AS ALP, Laboratory.TP AS TP, Laboratory.ALB AS ALB, Laboratory.UA AS UA, Laboratory.UN AS UN, Laboratory.CRE AS CRE, Laboratory.`T-BIL` AS `T-BIL`, Laboratory.`T-CHO` AS `T-CHO`, Laboratory.TG AS TG, Laboratory.CPK AS CPK, Laboratory.GLU AS GLU, Laboratory.WBC AS WBC, Laboratory.RBC AS RBC, Laboratory.HGB AS HGB, Laboratory.HCT AS HCT, Laboratory.PLT AS PLT, Laboratory.PT AS PT, Laboratory.APTT AS APTT, Laboratory.FG AS FG, Laboratory.PIC AS PIC, Laboratory.TAT AS TAT, Laboratory.TAT2 AS TAT2, Laboratory.`U-PRO` AS `U-PRO`, Laboratory.IGG AS IGG, Laboratory.IGA AS IGA, Laboratory.IGM AS IGM, Laboratory.CRP AS CRP, Laboratory.RA AS RA, Laboratory.RF AS RF, Laboratory.C3 AS C3, Laboratory.C4 AS C4, Laboratory.RNP AS RNP, Laboratory.SM AS SM, Laboratory.SC170 AS SC170, Laboratory.SSA AS SSA, Laboratory.SSB AS SSB, Laboratory.CENTROMEA AS CENTROMEA, Laboratory.DNA AS DNA, Laboratory.`DNA-II` AS `DNA-II`, Patient.SEX AS SEX, Patient.Birthday AS Birthday FROM Laboratory LEFT JOIN Patient AS Patient ON Laboratory.ID = Patient.ID) SELECT CAST(SUM(CASE WHEN Sex = 'F' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) as percentage;
FROM v_Examination e, v_Laboratory l
WHERE e.ID = l.ID AND e.Birthday > '1930' AND e.Sex = 'F'

